t.script:

document.addEventListener('DOMContentLoaded', function() {
    const app = document.getElementById('iq_app');
    const tasks = JSON.parse(app.dataset.tasks);
    const surveyId = app.dataset.survey;
    const maxTime = 20 * 60;

    // TIMER FIX: Use localStorage to persist start time
    const storageKey = 'iq_test_start_' + surveyId;
    let startTime = localStorage.getItem(storageKey);

    if (!startTime) {
        startTime = Math.floor(Date.now() / 1000);
        localStorage.setItem(storageKey, startTime);
    }

    let answers = {}; 
    let currentIndex = 0;
    const timerEl = document.getElementById('timer');

    const timerInterval = setInterval(() => {
        const now = Math.floor(Date.now() / 1000);
        const elapsed = now - parseInt(startTime);
        let timeLeft = maxTime - elapsed;

        if (timeLeft < 0) timeLeft = 0;

        const m = Math.floor(timeLeft / 60);
        const s = timeLeft % 60;
        timerEl.innerText = `${m}:${s < 10 ? '0' : ''}${s}`;

        if (timeLeft <= 0) {
            clearInterval(timerInterval);
            alert("Time is up! Submitting answers.");
            submitResults(elapsed);
        }
    }, 1000);

    function renderTask() {
        if (currentIndex >= tasks.length) {
            const now = Math.floor(Date.now() / 1000);
            const elapsed = now - parseInt(startTime);
            submitResults(elapsed);
            return;
        }
        const task = tasks[currentIndex];
        document.getElementById('q_code').innerText = task.code;
        document.getElementById('progress_badge').innerText = (currentIndex + 1) + " / " + tasks.length;
        document.getElementById('task_image').src = task.image;

        const container = document.getElementById('options_container');
        container.innerHTML = '';
        for (let i = 1; i <= task.options; i++) {
            let btn = document.createElement('button');
            btn.className = 'btn btn-outline-dark m-2 d-flex align-items-center justify-content-center';
            btn.innerText = i;
            btn.style.width = '50px';
            btn.style.height = '50px';
            btn.style.fontSize = '20px';
            btn.style.fontWeight = 'bold';
            btn.onclick = function() {
                answers[task.id] = i;
                currentIndex++;
                renderTask();
            };
            container.appendChild(btn);
        }
    }

    function submitResults(finalDuration) {
        clearInterval(timerInterval);
        localStorage.removeItem(storageKey); // Clear timer

        const appContainer = document.getElementById('iq_app');
        appContainer.innerHTML = '<div class="text-center mt-5"><h3>Calculating Results...</h3><div class="spinner-border text-primary" role="status"></div></div>';

        const submitParams = {
            survey_id: surveyId,
            name: app.dataset.name,
            age: app.dataset.age,
            email: app.dataset.email,
            applicant_id: app.dataset.applicant,
            answers: answers,
            duration: finalDuration
        };
        if (app.dataset.userInputId) submitParams.user_input_id = app.dataset.userInputId;
        if (app.dataset.etoken) submitParams.etoken = app.dataset.etoken;

        fetch('/iq-test/submit', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({
                jsonrpc: "2.0",
                method: "call",
                params: submitParams,
                id: new Date().getTime()
            })
        })
        .then(response => response.json())
        .then(result => {
            if (result.result && result.result.redirect_url) {
                window.location.href = result.result.redirect_url;
            } else {
                alert('Error submitting results.');
            }
        });
    }
    renderTask();
});
